SELECT Customers.name FROM Customers INNER JOIN Renting_history ON Customers.id = Renting_history.customer_id WHERE Renting_history.discount_id IN (SELECT Discount.id FROM Discount WHERE Discount.membership_credit > 0 AND Discount.name IS NOT NULL) AND COUNT(Renting_history.vehicles_id) > 2;
