SELECT S.student_id, S.amount_of_loan, S.date_of_loan, S.other_details FROM Students S JOIN Student_Loans L ON S.student_id = L.student_id JOIN Transcripts T ON S.student_id = T.student_id JOIN Behaviour_Monitoring BM ON S.student_id = BM.student_id JOIN Student_Events SE ON S.student_id = SE.student_id JOIN Classes C ON S.student_id = C.student_id JOIN Detention D ON S.student_id = D.student_id JOIN Students_Addresses SA ON S.student_id = SA.student_id JOIN Ref_Address_Types RA ON SA.address_type_code = RA.address_type_code JOIN Ref_Detention_Type DRT ON D.detention_type_code = DRT.detention_type_code JOIN Ref_Achievement_Type ATA ON ATA.achievement_type_code = Achievements.achievement_type_code JOIN Achievements A ON A.student_id = S.student_id WHERE A.date_achievement IS NOT NULL AND A.achievement_type_code IS NOT NULL AND A.achievement_details IS NOT NULL AND A.achievement_details IS NOT NULL AND A.date_achievement >= DATE_SUB(CURRENT_DATE, INTERVAL 2 DAY) AND A.achievement_details IS NOT NULL;
SELECT teachers.teacher_id, students.student_id, teachers.teacher_details FROM Teachers JOIN Students ON Teachers.teacher_id = Students.student_id JOIN Classes ON Classes.student_id = Students.student_id JOIN Teachers ON Classes.teacher_id = Teachers.teacher_id GROUP BY teachers.teacher_id, Students.student_id ORDER BY COUNT(Classes.class_details) DESC;
SELECT t.id, s.id FROM Teachers t JOIN Students s ON t.teacher_id = s.student_id JOIN Classes c ON c.student_id = s.id JOIN Transcripts t_trans ON t_trans.transcript_id = t.id JOIN Student_Loans l ON l.student_id = s.id JOIN Detention d ON d.student_id = s.id JOIN Student_Addresses sa ON sa.student_id = s.id JOIN Addresses a ON sa.address_id = a.address_id JOIN Ref_Address_Types r ON sa.address_type_code = r.address_type_code JOIN Ref_Detention_Type dt ON d.detention_type_code = dt.detention_type_code;
