SELECT Students.student_id, Students.bio_data, Students.student_details, Ref_Address_Types.address_type_description, Ref_Detention_Type.detention_type_description, Ref_Achievement_Type.achievement_type_description, Ref_Event_Types.event_type_description, Detention.datetime_detention_start, Detention.datetime_detention_end, Detention.detention_summary, Detention.other_details FROM Students JOIN Ref_Address_Types ON Students.student_id = Ref_Address_Types.address_type_code JOIN Ref_Detention_Type ON Students.student_id = Ref_Detention_Type.detention_type_code JOIN Ref_Achievement_Type ON Students.student_id = Ref_Achievement_Type.achievement_type_code JOIN Ref_Event_Types ON Students.student_id = Ref_Event_Types.event_type_code JOIN Detention ON Students.student_id = Detention.student_id;
