SELECT Students.student_id, Students.bio_data, Students.student_details, Addresses.address_details FROM Students JOIN Addresses ON Students.student_id = Addresses.address_id JOIN Students_Addresses ON Students.student_id = Students_Addresses.student_id JOIN Addresses AS address_details ON Students_Addresses.address_id = address_details.address_id;
SELECT Students.student_id, Students.bio_data, Students.student_details, Addresses.address_details, Detention.datetime_detention_start, Detention.detention_summary FROM Students INNER JOIN Addresses ON Students.student_id = Addresses.address_id INNER JOIN Detention ON Addresses.address_id = Detention.student_id;
