SELECT s.student_id, t.student_id, t.teacher_id, t.class_details FROM Students s JOIN Transcripts t ON s.student_id = t.student_id JOIN Classes c ON t.student_id = c.student_id JOIN Behaviour_Monitoring b ON s.student_id = b.student_id JOIN Student_Events e ON s.student_id = e.student_id JOIN Ref_Event_Types e_type ON e.event_type_code = e_type.event_type_code JOIN Ref_Address_Types a_type ON e.address_type_code = a_type.address_type_code JOIN Addresses a ON e.address_id = a.address_id JOIN Detention d ON s.student_id = d.student_id JOIN Ref_Detention_Type dt ON d.detention_type_code = dt.detention_type_code JOIN Ref_Address_Types a_t ON e.address_type_code = a_t.address_type_code JOIN Ref_Achievement_Type a_at ON e.achievement_type_code = a_at.achievement_type_code JOIN Achievements a_ach ON e.achievement_id = a_ach.achievement_id;
SELECT COUNT(*) AS total_courses, teacher_id AS teacher_id FROM Classes GROUP BY teacher_id ORDER BY COUNT(*) DESC;
SELECT teacher_id, COUNT(Classes.class_id) AS number_of_courses FROM Classes INNER JOIN Teachers ON Classes.teacher_id = Teachers.teacher_id GROUP BY teacher_id;
SELECT COUNT(*) AS max_courses, student_id AS student_id FROM Transcripts GROUP BY student_id ORDER BY COUNT(*) DESC LIMIT 1;
SELECT student_id, COUNT(*) AS course_count FROM Transcripts JOIN Students ON Transcripts.student_id = Students.student_id GROUP BY student_id;
SELECT student_id, student_details FROM Students INNER JOIN Transcripts ON Transcripts.student_id = Students.student_id WHERE Transcripts.transcript_details IS NOT NULL;
SELECT student_id, transcript_details FROM Transcripts JOIN Students ON Transcripts.student_id = Students.student_id WHERE Transcripts.transcript_details LIKE '%2 courses%';
SELECT Detention.detention_type_code, Detention.detention_type_description, Detention.detention_summary FROM Detention WHERE Detention.student_id IN (SELECT student_id FROM Student_Events WHERE event_type_code = 'B' OR event_type_code = 'D') ORDER BY Detention.detention_type_code ASC LIMIT 1;
SELECT detention_type_code, detention_type_description FROM Ref_Detention_Type ORDER BY detention_type_code ASC LIMIT 1;
SELECT Students.bio_data, Students.student_id, Students_Addresses.address_id, Addresses.address_details, Detention.datetime_detention_start, Detention.detention_summary FROM Students JOIN Students_Addresses ON Students.student_id = Students_Addresses.student_id JOIN Addresses ON Students_Addresses.address_id = Addresses.address_id JOIN Detention ON Detention.student_id = Students.student_id WHERE Student_Loans.amount_of_loan > (SELECT AVG(Student_Loans.amount_of_loan) FROM Student_Loans) ORDER BY Students_Addresses.address_id;
SELECT S.student_id, S.bio_data, S.student_details, S.student_loan_id, S.amount_of_loan, S.other_details FROM Students S JOIN Student_Loans SL ON S.student_id = SL.student_id WHERE SL.amount_of_loan > (SELECT AVG(S.amount_of_loan) FROM Student_Loans SL) ORDER BY S.student_id
SELECT MIN(date_of_loan) FROM Student_Loans;
SELECT MIN(date_of_loan) FROM Student_Loans;
SELECT Students.student_id, Students.bio_data, Students.student_details FROM Students JOIN Transcripts ON Transcripts.student_id = Students.student_id JOIN Behaviour_Monitoring ON Behaviour_Monitoring.student_id = Students.student_id JOIN Student_Loans ON Student_Loans.student_id = Students.student_id WHERE Student_Loans.amount_of_loan = (SELECT MIN(amount_of_loan) FROM Student_Loans);
