SELECT Name FROM Client WHERE Name IN (SELECT Name FROM Orders JOIN Books_Order ON Orders.IdClient = Books_Order.IdClient JOIN Author_Book ON Books_Order.ISBN = Author_Book.ISBN JOIN Author ON Author.ISBN = Author_Book.Author) AND DateOrder IS NOT NULL;
