SELECT DISTINCT participants.popularity AS distinct_stage_presence_score FROM participants JOIN songs ON participants.id = songs.id WHERE songs.language = 'English';
SELECT p.id, p.name FROM participants p JOIN performance_score ps ON p.id = ps.participant_id WHERE ps.songs_id IN (SELECT songs.id FROM songs s JOIN performance_score ps ON s.id = ps.songs_id GROUP BY songs.id HAVING ps.songs_id > 0)
SELECT participants.id, participants.name, participants.popularity, performances.songs_id, performances.voice_sound_quality, performances.rhythm_tempo, performances.stage_presence FROM participants JOIN performances ON performances.participant_id = participants.id ORDER BY participants.popularity;
