SELECT participants.name, participants.popularity FROM participants JOIN performance_score ON participants.id = performance_score.participant_id JOIN songs ON performance_score.songs_id = songs.id WHERE songs.language = 'Croatian' AND songs.language = 'English' AND performance_score.songs_id = songs.id;
