SELECT Features.feature_name, Features.feature_description FROM Features;
SELECT Features.feature_description FROM Features JOIN Property_Features ON Features.feature_id = Property_Features.feature_id WHERE Features.feature_name = 'rooftop'
SELECT Features.feature_name, Features.feature_description FROM Features JOIN Property_Features ON Features.feature_id = Property_Features.feature_id JOIN Properties ON Property_Features.property_id = Properties.property_id WHERE Properties.property_type_code = (SELECT property_type_code FROM Ref_Property_Types WHERE property_type_code IN ('Garage', 'Parking')) ORDER BY Features.feature_name ASC
SELECT F.feature_name, F.feature_description, F.feature_value, F.feature_id FROM Features F INNER JOIN Property_Features PF ON F.feature_id = PF.feature_id INNER JOIN Properties P ON PF.property_id = P.property_id INNER JOIN Ref_Property_Types PT ON P.property_type_code = PT.property_type_code INNER JOIN Ref_Room_Types RT ON P.room_type_code = RT.room_type_code;
