SELECT author.Name, press.Month_Profits_billion AS Month_Profits, book.Sale_Amount AS Total_Sale_Amount FROM book INNER JOIN author ON book.Author_ID = author.Author_ID INNER JOIN press ON book.Press_ID = press.Press_ID;
