SELECT author.Name, book.Book_Series FROM book INNER JOIN author ON book.Author_ID = author.Author_ID;
SELECT author.Name, author.Gender FROM author JOIN book ON author.Author_ID = book.Author_ID JOIN press ON book.Press_ID = press.Press_ID GROUP BY author.Name, author.Gender ORDER BY book.Release_date DESC;
