SELECT Clients.client_id, Clients.client_details, COUNT(Meetings.meeting_id) AS meeting_count FROM Clients JOIN Agencies ON Clients.agency_id = Agencies.agency_id JOIN Staff ON Clients.client_id = Staff.client_id JOIN Meetings ON Clients.client_id = Staff_in_Meetings.meeting_id GROUP BY Clients.client_id
SELECT DISTINCT m.meeting_type, COUNT(*) AS total_meetings FROM Meetings m JOIN Staff_in_Meetings s ON m.meeting_id = s.meeting_id GROUP BY m.meeting_type;
SELECT M.meeting_id, M.meeting_outcome, M.meeting_type, M.client_id, M.purpose_of_meeting, M.billable_yn, M.start_date_time, M.end_date_time, M.other_details FROM Meetings M JOIN Clients C ON M.client_id = C.client_id JOIN Staff S ON S.staff_id = S.staff_id JOIN Staff_in_Meetings S_M ON S_M.meeting_id = M.meeting_id JOIN Agencies A ON C.agency_id = A.agency_id;
SELECT M.meeting_id, M.meeting_outcome, M.meeting_type, C.client_id, C.client_details FROM Meetings M JOIN Clients C ON M.client_id = C.client_id;
SELECT m.meeting_id, COUNT(s.staff_id) AS staff_count FROM Meetings m JOIN Staff s ON m.client_id = s.client_id GROUP BY m.meeting_id;
SELECT COUNT(*) AS count FROM Staff_in_Meetings JOIN Meetings ON Staff_in_Meetings.meeting_id = Meetings.meeting_id;
SELECT staff.staff_id, COUNT(*) AS meeting_attendance FROM Staff JOIN Staff_in_Meetings ON Staff.staff_id = Staff_in_Meetings.staff_id JOIN Meetings ON Staff_in_Meetings.meeting_id = Meetings.meeting_id WHERE Meetings.purpose_of_meeting = 'some meeting' GROUP BY Staff.staff_id ORDER BY meeting_attendance ASC
SELECT staff.staff_id FROM Staff INNER JOIN Staff_in_Meetings ON Staff.staff_id = Staff_in_Meetings.staff_id WHERE Staff_in_Meetings.meeting_type = 'some meeting' AND Staff_in_Meetings.meeting_outcome = 'attended' AND Staff_in_Meetings.meeting_type IS NOT NULL;
SELECT COUNT(*) FROM Staff INNER JOIN Staff_in_Meetings ON Staff.staff_id = Staff_in_Meetings.staff_id;
SELECT COUNT(DISTINCT staff.staff_id) FROM Staff;
SELECT COUNT(*) AS total_staffs FROM Staff INNER JOIN Staff_in_Meetings ON Staff.staff_id = Staff_in_Meetings.staff_id;
SELECT COUNT(*) FROM Staff INNER JOIN Staff_in_Meetings ON Staff.staff_id = Staff_in_Meetings.staff_id WHERE Staff_in_Meetings.meeting_id IS NULL;
