SELECT staff.staff_id, staff.staff_details, meetings.client_id, meetings.meeting_type, meetings.billable_yn, meetings.start_date_time, meetings.end_date_time, meetings.purpose_of_meeting, meetings.other_details FROM Staff JOIN Staff_in_Meetings ON Staff.staff_id = Staff_in_Meetings.staff_id JOIN Meetings ON Staff_in_Meetings.meeting_id = Meetings.meeting_id WHERE meetings.client_id IN (SELECT client_id FROM Clients WHERE Clients.sic_code LIKE 's%')
SELECT S.staff_id, S.staff_details FROM Staff S JOIN Staff_in_Meetings SSM ON S.staff_id = SSM.staff_id JOIN Meetings M ON SSM.meeting_id = M.meeting_id WHERE S.staff_details LIKE '%s%' AND M.client_id = S.client_id;
SELECT Clients.id, Clients.sic_code, Agencies.agency_id FROM Clients INNER JOIN Agencies ON Clients.agency_id = Agencies.agency_id WHERE Clients.client_id IN (SELECT client_id FROM Meetings WHERE meeting_outcome = 'attended' OR meeting_outcome = 'any_invoice')
SELECT Clients.client_id, Clients.sic_code, Clients.agency_id, Clients.client_details, Staff_in_Meetings.staff_id, Staff_in_Meetings.meeting_id FROM Clients JOIN Staff_in_Meetings ON Clients.client_id = Staff_in_Meetings.meeting_id JOIN Meetings ON Staff_in_Meetings.meeting_id = Meetings.meeting_id JOIN Staff ON Staff.staff_id = Staff_in_Meetings.staff_id WHERE Clients.agency_id = Agencies.agency_id AND Meetings.meeting_type = 'Meeting' AND Meetings.billable_yn = 'Y' AND Meetings.start_date_time IS NOT NULL AND Meetings.end_date_time IS NOT NULL AND Clients.client_details IS NOT NULL;
SELECT M.start_date_time, M.end_date_time, C.client_id, S.staff_id FROM Meetings M JOIN Clients C ON M.client_id = C.client_id JOIN Staff S ON S.staff_id = M.staff_id;
SELECT m.start_date_time, m.end_date_time, s.staff_id, s.staff_details, c.client_id, c.client_details FROM Meetings m JOIN Staff s ON m.meeting_id = s.meeting_id JOIN Clients c ON m.client_id = c.client_id;
